const data = require('fs').readFileSync(0, 'utf8').split(/\s+/);
let n = parseInt(data[0]), k = parseInt(data[1]);

function isLucky(x) {
  if (x <= 0) return false;
  while (x > 0) {
    const d = x % 10;
    if (d !== 4 && d !== 7) return false;
    x = Math.floor(x / 10);
  }
  return true;
}

function luckyCount(X) {
  if (X < 4) return 0;
  let cnt = 0;
  const stack = [4, 7];
  while (stack.length) {
    const v = stack.pop();
    if (v <= X) {
      cnt++;
      if (v * 10 + 4 <= X) stack.push(v * 10 + 4);
      if (v * 10 + 7 <= X) stack.push(v * 10 + 7);
    }
  }
  return cnt;
}

const m = Math.min(n, 13);
let f = 1;
for (let i = 1; i <= m; i++) f *= i;

if (f < k) {
  console.log(-1);
} else {
  let count = luckyCount(n - m);
  const arr = [];
  for (let i = n - m + 1; i <= n; i++) arr.push(i);
  let kk = k - 1;
  for (let i = 0; i < m; i++) {
    let fct = 1;
    for (let j = 1; j <= m - 1 - i; j++) fct *= j;
    const idx = Math.floor(kk / fct);
    kk = kk % fct;
    const val = arr[idx];
    arr.splice(idx, 1);
    const pos = n - m + 1 + i;
    if (isLucky(pos) && isLucky(val)) count++;
  }
  console.log(count);
}
